#!/usr/bin/env python3
"""Fetch every orders page and every referenced customer from the order service.

Usage: python3 -I fetch.py OUTDIR

Writes OUTDIR/pages/page_NNN.json, OUTDIR/customers.json and OUTDIR/fetch.log.
Never guesses: every failed request is repeated until it succeeds (or the
attempt cap is hit, in which case the script aborts rather than continue).
"""
import json
import os
import sys
import time
import urllib.error
import urllib.parse
import urllib.request

BASE = "http://localhost:8080"
MAX_ATTEMPTS = 200
PAGE_SIZE = 50


class Client:
    def __init__(self, logf):
        self.token = None
        self.logf = logf
        self.stats = {}
        self.requests = 0

    def log(self, msg):
        line = f"{time.strftime('%H:%M:%S')} {msg}"
        self.logf.write(line + "\n")
        self.logf.flush()

    def bump(self, key):
        self.stats[key] = self.stats.get(key, 0) + 1

    def _raw(self, method, path, auth):
        req = urllib.request.Request(BASE + path, method=method)
        if auth:
            req.add_header("Authorization", f"Bearer {self.token}")
        self.requests += 1
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, dict(r.headers), r.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers), e.read()

    @staticmethod
    def _retry_after(headers, body):
        waits = []
        for k, v in headers.items():
            if k.lower() == "retry-after":
                try:
                    waits.append(float(v))
                except ValueError:
                    pass
        try:
            ra = json.loads(body).get("retry_after")
            if ra is not None:
                waits.append(float(ra))
        except Exception:
            pass
        return max(waits) if waits else 1.0

    def get_token(self):
        status, data = self.request("/token", method="POST", auth=False)
        if status != 200 or not isinstance(data, dict) or not data.get("token"):
            raise RuntimeError(f"unexpected token response {status} {data!r}")
        self.bump("tokens_fetched")
        self.log(f"new token {data['token']}")
        return data["token"]

    def request(self, path, method="GET", auth=True, final_statuses=(404,)):
        """Return (status, parsed_json). Retries until 200 or a status in final_statuses."""
        for attempt in range(1, MAX_ATTEMPTS + 1):
            if auth and self.token is None:
                self.token = self.get_token()
            try:
                status, headers, body = self._raw(method, path, auth)
            except Exception as e:  # connection reset, timeout, ...
                self.bump("transport_error")
                self.log(f"{method} {path}: transport error {e!r}; retrying")
                time.sleep(min(0.25 * attempt, 3))
                continue
            snippet = body[:160].decode("utf-8", "replace")
            if status == 429:
                wait = self._retry_after(headers, body)
                self.bump("429")
                self.log(f"{method} {path}: 429 {snippet!r}; waiting {wait}s")
                time.sleep(wait + 0.05)
                continue
            if status == 401 and auth:
                self.bump("401")
                self.log(f"{method} {path}: 401 {snippet!r}; refreshing token")
                self.token = None
                continue
            if status == 200 or status in final_statuses:
                try:
                    data = json.loads(body)
                except ValueError:
                    self.bump("bad_json")
                    self.log(f"{method} {path}: {status} with unparseable body {snippet!r}; retrying")
                    time.sleep(min(0.25 * attempt, 3))
                    continue
                return status, data
            self.bump(str(status))
            self.log(f"{method} {path}: {status} {snippet!r}; retrying")
            wait = self._retry_after(headers, body) if any(
                k.lower() == "retry-after" for k in headers) else min(0.25 * attempt, 3)
            time.sleep(wait)
        raise RuntimeError(f"giving up on {method} {path} after {MAX_ATTEMPTS} attempts")


def page_of(path):
    q = urllib.parse.parse_qs(urllib.parse.urlparse(path).query)
    return int(q["page"][0])


def fetch_page(client, n):
    """Fetch page n and validate its shape; repeat on a malformed 200."""
    path = f"/orders?page={n}"
    for attempt in range(1, MAX_ATTEMPTS + 1):
        status, data = client.request(path, final_statuses=())
        problems = []
        if not isinstance(data, dict):
            problems.append("not an object")
        else:
            if data.get("page") != n:
                problems.append(f"page field {data.get('page')!r} != {n}")
            if not isinstance(data.get("items"), list):
                problems.append("items not a list")
            if not isinstance(data.get("total_pages"), int):
                problems.append("total_pages not int")
            if "next" not in data:
                problems.append("no next field")
        if not problems:
            return data
        client.bump("malformed_page")
        client.log(f"page {n}: malformed 200 ({'; '.join(problems)}); retrying")
        time.sleep(min(0.25 * attempt, 3))
    raise RuntimeError(f"page {n}: still malformed after {MAX_ATTEMPTS} attempts")


def main():
    outdir = sys.argv[1]
    os.makedirs(os.path.join(outdir, "pages"), exist_ok=True)
    logf = open(os.path.join(outdir, "fetch.log"), "w")
    client = Client(logf)

    pages = {}
    chain = []          # sequence of page numbers reached by following "next"
    n = 1
    while n is not None:
        if n in pages:
            raise RuntimeError(f"next-chain loops back to page {n}")
        data = fetch_page(client, n)
        pages[n] = data
        chain.append(n)
        with open(os.path.join(outdir, "pages", f"page_{n:03d}.json"), "w") as f:
            json.dump(data, f)
        nxt = data["next"]
        n = page_of(nxt) if nxt else None
        if len(chain) > 10000:
            raise RuntimeError("runaway pagination")

    totals = {d["total_pages"] for d in pages.values()}
    client.log(f"next-chain visited {chain}; total_pages values seen {sorted(totals)}")
    # Make sure every page 1..total_pages was fetched, even if the next-chain skipped one.
    for tp in totals:
        for m in range(1, tp + 1):
            if m not in pages:
                client.log(f"page {m} not reached via next-chain; fetching directly")
                data = fetch_page(client, m)
                pages[m] = data
                with open(os.path.join(outdir, "pages", f"page_{m:03d}.json"), "w") as f:
                    json.dump(data, f)

    customer_ids = sorted({o["customer_id"] for d in pages.values() for o in d["items"]})
    customers = {}
    for cid in customer_ids:
        status, data = client.request("/customers/" + urllib.parse.quote(str(cid), safe=""))
        if status == 404:
            # Docs say 404 means unknown id; confirm it is stable before believing it.
            confirmations = []
            for _ in range(3):
                time.sleep(0.2)
                s2, d2 = client.request("/customers/" + urllib.parse.quote(str(cid), safe=""))
                confirmations.append(s2)
                if s2 == 200:
                    status, data = s2, d2
                    break
            client.log(f"customer {cid}: initial 404, re-checks {confirmations}")
        customers[cid] = {"status": status, "body": data}

    with open(os.path.join(outdir, "customers.json"), "w") as f:
        json.dump(customers, f, indent=1, sort_keys=True)
    summary = {
        "requests": client.requests,
        "stats": client.stats,
        "chain": chain,
        "total_pages_seen": sorted(totals),
        "pages_fetched": sorted(pages),
        "customers_fetched": len(customers),
    }
    with open(os.path.join(outdir, "fetch_summary.json"), "w") as f:
        json.dump(summary, f, indent=1)
    print(json.dumps(summary, indent=1))


if __name__ == "__main__":
    main()

